mixin Logger on Object {
  void log(String m) => print('[$runtimeType] $m');
}

extension StringX on String {
  String get capitalized =>
      isEmpty ? this : this[0].toUpperCase() + substring(1);
}

sealed class Result {}
class Ok extends Result { Ok(this.v); final int v; }
class Err extends Result { Err(this.msg); final String msg; }

String show(Result r) => switch (r) {
  Ok(:final v) => 'ok $v',
  Err(:final msg) => 'error $msg',
};

